a <- grep("^--file=",commandArgs(FALSE),value=TRUE)
if (!length(a)) stop("Run with Rscript")
folder <- dirname(normalizePath(sub("^--file=","",a[1])))
item_name <- "Lázaro_etal_2021_Table3";root <- dirname(folder)
s <- utils::read.csv(file.path(folder,paste0(item_name,"_snapshot.csv")),check.names=FALSE,colClasses="character",fileEncoding="UTF-8")
stopifnot(nrow(s)==9L,ncol(s)==13L)
pm <- function(x) { z <- strsplit(x," ± ",fixed=TRUE);stopifnot(all(lengths(z)==2L)); matrix(as.numeric(unlist(z)),ncol=2L,byrow=TRUE) }
summer <- pm(s[[4]]); winter <- pm(s[[7]]); adult <- pm(s[[10]])
pct <- function(x) as.numeric(gsub("[−%]","",x))*ifelse(grepl("−",x,fixed=TRUE),-1,1)
sw <- pct(s[[12]]);wa <- pct(s[[13]])
check_sw <- 100*(winter[,1]/summer[,1]-1);check_wa <- 100*(adult[,1]/winter[,1]-1)
if (any(abs(check_sw-sw)>0.7 | abs(check_wa-wa)>0.7)) warning("Published percentage does not match displayed stage means for at least one row; source values retained")
out <- data.frame(source_row=seq_len(nrow(s)),species_as_published="Sorex araneus",measure_as_published=s[[1]],population_as_published=s[[2]],summer_n=as.integer(s[[3]]),summer_mean=summer[,1],summer_SE=summer[,2],summer_period=s[[5]],winter_n=as.integer(s[[6]]),winter_mean=winter[,1],winter_SE=winter[,2],winter_period=s[[8]],adult_n=as.integer(s[[9]]),adult_mean=adult[,1],adult_SE=adult[,2],adult_period=s[[11]],summer_to_winter_percent_as_published=sw,winter_to_adult_percent_as_published=wa,summer_to_winter_recomputed_from_printed_means=check_sw,winter_to_adult_recomputed_from_printed_means=check_wa,source_percent_check=ifelse(abs(check_sw-sw)>0.7 | abs(check_wa-wa)>0.7,"inconsistent with printed means","within 0.7 percentage point"),unit=ifelse(s[[1]]=="BCH (mm)","mm",ifelse(s[[1]]=="Body mass (g)","g","g/mm")),observation_level="population × season summary",data_role="primary grouped summary; overlaps source raw data",stringsAsFactors=FALSE)
utils::write.csv(out,file.path(folder,paste0(item_name,".csv")),row.names=FALSE,na="",fileEncoding="UTF-8")
reg <- readxl::read_excel(file.path(root,"__ReadMe.xlsx"),sheet="Sheet1")
hit <- which(reg[["Item name"]]==item_name);if(length(hit)!=1L) stop("Expected one main registry row")
encoded <- as.character(reg[["Item encoded"]][hit])
utils::write.table(out,file.path(root,"__Public","comparative-data",paste0(encoded,".tsv")),sep="\t",row.names=FALSE,na="",fileEncoding="UTF-8")
cat(item_name,": ",nrow(out)," source rows; published changes compared with rounded means\n",sep="")
